// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Receiver rec;

    function setUp() public { c = new airPort(); rec = new Receiver(); }

    // fuzzed params: from address, value v, and a single recipient address 'to'
    function testFuzz_property(address from, uint256 v, address to) public {
        // keep addresses non-zero to be in an admissible domain
        vm.assume(from != address(0));
        vm.assume(to != address(0));

        // Build a single-recipient array; this is the critical case differentiating P and M
        address[] memory tos = new address[](1);
        tos[0] = address(rec);

        // The reference contract should accept this call (not revert) for ANY inputs when _tos.length == 1.
        // We observe success/failure via try/catch on the external call.
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert that the call succeeds. The mutant (which requires _tos.length > 1) will revert
        // for these inputs and make this assertion fail for some fuzzed inputs (specifically all inputs
        // where tos.length == 1).
        assertTrue(ok);
    }
}

// Minimal adversarial/observing helper: matches the selector transferFrom(address,address,uint256)
contract Receiver {
    // record number of times called and last args to make this a meaningful callee
    uint public calls;
    address public lastFrom;
    address public lastTo;
    uint public lastV;

    // The function signature must match what C calls via abi.encodeWithSelector
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        return true;
    }
}
